<script setup lang="ts">
const route=useRoute(),{lang,local}=useLocale(); const {data:country,error}=await useFetch<any>(`/api/catalog/countries/${route.params.id}`); if(error.value) throw createError({statusCode:404}); const {data:numbers}=await useFetch<any[]>('/api/numbers',{query:{country:route.params.id}}); const name=computed(()=>lang.value==='ru'?country.value?.nameRu:country.value?.nameEn)
usePageSeo(computed(()=>lang.value==='ru'?`Виртуальные номера ${name.value} (${country.value?.phoneCode}) для SMS`:`${name.value} virtual numbers for SMS`),computed(()=>lang.value==='ru'?`Временные виртуальные номера ${name.value} с кодом ${country.value?.phoneCode}: формат телефона, демонстрационная SMS-лента и правила безопасного использования.`:`Temporary ${name.value} virtual numbers, calling code ${country.value?.phoneCode}, simulated SMS feed, and safety guidance.`))
const config=useRuntimeConfig(); useHead({script:[{type:'application/ld+json',innerHTML:computed(()=>JSON.stringify({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:lang.value==='ru'?'Главная':'Home',item:config.public.siteUrl},{'@type':'ListItem',position:2,name:lang.value==='ru'?'Страны':'Countries',item:`${config.public.siteUrl}/countries`},{'@type':'ListItem',position:3,name:name.value,item:`${config.public.siteUrl}/countries/${country.value?.id}`}]}))}]})
</script>
<template><div class="shell page"><nav class="crumbs"><NuxtLink :to="local('/countries')">{{lang==='ru'?'Страны':'Countries'}}</NuxtLink> / {{name}}</nav><div class="country-title"><img :src="`/images/countries/${country.id}.svg`" :alt="lang==='ru'?`Флаг: ${name}`:`${name} flag`"><div><span class="kicker">{{country.phoneCode}} / Virtual phone</span><h1>{{lang==='ru'?`Виртуальные номера ${name} для SMS`:`${name} virtual SMS numbers`}}</h1></div></div><p class="lead">{{lang==='ru'?`Выберите временный номер ${name} с международным кодом ${country.phoneCode} и изучите формат входящих кодов подтверждения. Демонстрационный набор обновляется каждый час и не обеспечивает реальную доставку SMS.`:`Choose a temporary ${name} number with calling code ${country.phoneCode} and explore verification-code formats. The simulated set refreshes hourly and does not provide real SMS delivery.`}}</p><div class="number-grid"><NumberCard v-for="n in numbers" :key="n.id" :number="n"/></div><PremiumBanner medium="number_expired"/><SeoCopy :subject="name" type="country"/></div></template>
